  { nombre: "Tumbes", lat: -3.57, lon: -80.45 },
  { nombre: "Ucayali", lat: -8.38, lon: -74.55 }
];

function getDepartamento(lat, lon) {
  let masCercano = null;
  let distanciaMin = Infinity;

  for (const dep of departamentos) {
    const dist = Math.sqrt(Math.pow(lat - dep.lat, 2) + Math.pow(lon - dep.lon, 2));
    if (dist < distanciaMin) {
      distanciaMin = dist;
      masCercano = dep.nombre;
    }
  }

  return masCercano || "Desconocido";
}

// Función para calcular semana epidemiológica y año (ISO week)
function getSemanaEpi(fechaStr) {
  const fecha = new Date(fechaStr);
  const target = new Date(fecha.valueOf());
  const dayNr = (fecha.getDay() + 6) % 7;
  target.setDate(target.getDate() - dayNr + 3);
  const firstThursday = target.valueOf();
  target.setMonth(0, 1);
  if (target.getDay() !== 4) {
    target.setMonth(0, 1 + ((4 - target.getDay()) + 7) % 7);
  }
  const semana = 1 + Math.ceil((firstThursday - target) / 604800000);
  const anio = new Date(fecha.getFullYear(), 0, 4).getFullYear();
  return { anio, semana };
}

for (const item of items) {
  const responses = Array.isArray(item.json) ? item.json : [item.json];

  for (const response of responses) {
    const data = response.daily;
    if (!data || !data.time) continue;

    const nombreDepartamento = getDepartamento(response.latitude, response.longitude);

    const grupos = {};

    for (let i = 0; i < data.time.length; i++) {
      const { anio, semana } = getSemanaEpi(data.time[i]);
      const key = `${anio}-${semana}`;

      if (!grupos[key]) {
        grupos[key] = {
          anio,
          semana,
          temp_max: [],
          temp_min: [],
          temp_mean: [],
          precipitacion: [],
          humedad: []
        };
      }

      grupos[key].temp_max.push(data.temperature_2m_max[i]);
      grupos[key].temp_min.push(data.temperature_2m_min[i]);
      grupos[key].temp_mean.push(data.temperature_2m_mean[i]);
      grupos[key].precipitacion.push(data.precipitation_sum[i]);
      grupos[key].humedad.push(data.relative_humidity_2m_mean[i]);
    }

    const promedio = arr => (arr.reduce((a, b) => a + b, 0) / arr.length);
    const suma = arr => arr.reduce((a, b) => a + b, 0);

    for (const key in grupos) {
      const g = grupos[key];
      output.push({
        json: {
          departamento: nombreDepartamento,
          latitud: response.latitude,
          longitud: response.longitude,
          ano: g.anio,
          semana_epi: g.semana,
          temp_max_promedio: Number(promedio(g.temp_max).toFixed(1)),
          temp_min_promedio: Number(promedio(g.temp_min).toFixed(1)),
          temp_mean_promedio: Number(promedio(g.temp_mean).toFixed(1)),
          precipitacion_total: Number(suma(g.precipitacion).toFixed(1)),
          humedad_promedio: Number(promedio(g.humedad).toFixed(1))
        }
      });
    }
  }
}

return output;
